INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass eine Systemeinführung immer ohne Tests erfolgt?', 2, '[{"text": "Nein", "correct": true, "because": "Tests sind essenziell"}, {"text": "Ja", "correct": false, "because": "Tests minimieren Fehler"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phase ist entscheidend vor der Einführung einer Software?', 3, '[{"text": "Testphase", "correct": true, "because": "Sichert Stabilität"}, {"text": "Marketing", "correct": false, "because": "Sekundär"}, {"text": "Dokumentation", "correct": false, "because": "Unterstützend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte machen eine Einführung erfolgreich?', 5, '[{"text": "Planung", "correct": true, "because": "Strukturiert den Prozess"}, {"text": "Schulung", "correct": true, "because": "Bereitet Nutzer vor"}, {"text": "Farbanpassung", "correct": false, "because": "Kosmetisch"}, {"text": "Schnelles Release", "correct": false, "because": "Risiko für Fehler"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Pilotphasen testen die Einführung. b) Sie ersetzen die finale Einführung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Pilot ist Vorbereitung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Planung einer Einführung?', 4, '[{"text": "Nutzerakzeptanz", "correct": false, "because": "Entscheidend für Erfolg"}, {"text": "Ressourcen", "correct": false, "because": "Bestimmen Machbarkeit"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Einführung immer global erfolgt?', 2, '[{"text": "Nein", "correct": true, "because": "Kann regional oder schrittweise sein"}, {"text": "Ja", "correct": false, "because": "Flexibel gestaltbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool unterstützt die Koordination einer Einführung?', 4, '[{"text": "Projektmanagement-Software", "correct": true, "because": "Strukturiert Aufgaben"}, {"text": "Texteditor", "correct": false, "because": "Nur für Dokumente"}, {"text": "Grafikprogramm", "correct": false, "because": "Kein Koordinationswerkzeug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Einführung ohne Schulung möglich ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Schulung fördert Akzeptanz"}, {"text": "Ja", "correct": false, "because": "Ohne Schulung mehr Fehler"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Pilotprojekt zwingend?', 2, '[{"text": "Nein", "correct": true, "because": "Hilfreich, aber optional"}, {"text": "Ja", "correct": false, "because": "Abhängig von Projekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren sichern eine reibungslose Einführung?', 5, '[{"text": "Testläufe", "correct": true, "because": "Finden Schwachstellen"}, {"text": "Kommunikation", "correct": true, "because": "Klärt Nutzer auf"}, {"text": "Schnelles Tempo", "correct": false, "because": "Risiko für Fehler"}, {"text": "Minimale Planung", "correct": false, "because": "Führt zu Chaos"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei einer Einführung priorisieren?', 4, '[{"text": "Nutzerfeedback", "correct": true, "because": "Verbessert Akzeptanz"}, {"text": "Schnelles Release", "correct": false, "because": "Qualität wichtiger"}, {"text": "Minimale Tests", "correct": false, "because": "Erhöht Risiken"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Phasenweise Einführung reduziert Risiken. b) Sie dauert immer länger.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, kann effizient sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine erfolgreiche Einführung?', 3, '[{"text": "Planung", "correct": false, "because": "Strukturiert Prozess"}, {"text": "Tests", "correct": false, "because": "Sichern Qualität"}, {"text": "Dekoration", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich eine Einführung vorbereite?', 4, '[{"text": "Pilot testen und Nutzer schulen", "correct": true, "because": "Minimiert Risiken"}, {"text": "Nur Dokumente schreiben", "correct": false, "because": "Zu eingeschränkt"}, {"text": "Ohne Plan starten", "correct": false, "because": "Führt zu Chaos"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Einführungen immer fehlerfrei sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Fehler sind möglich"}, {"text": "Ja", "correct": false, "because": "Tests minimieren, eliminieren nicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip hilft, Risiken bei der Einführung zu minimieren?', 3, '[{"text": "Phasenweiser Ansatz", "correct": true, "because": "Ermöglicht Anpassungen"}, {"text": "Schnelles Release", "correct": false, "because": "Erhöht Risiken"}, {"text": "Keine Tests", "correct": false, "because": "Gefährdet Qualität"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine Einführung ohne Planung möglich?', 2, '[{"text": "Nein", "correct": true, "because": "Planung ist essenziell"}, {"text": "Ja", "correct": false, "because": "Risiko für Chaos"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gut geplante Einführung?', 5, '[{"text": "Geringere Fehlerquote", "correct": true, "because": "Tests fangen Probleme"}, {"text": "Höhere Akzeptanz", "correct": true, "because": "Schulung hilft Nutzern"}, {"text": "Schnellere Entwicklung", "correct": false, "because": "Nicht primär"}, {"text": "Weniger Dokumentation", "correct": false, "because": "Unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Einführung unwichtig?', 3, '[{"text": "Nutzerfeedback", "correct": false, "because": "Verbessert Prozess"}, {"text": "Testumgebung", "correct": false, "because": "Sichert Stabilität"}, {"text": "Launch-Party", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ein System eingeführt wird?', 4, '[{"text": "Planen, testen, schulen", "correct": true, "because": "Umfassender Ansatz"}, {"text": "Nur installieren", "correct": false, "because": "Zu riskant"}, {"text": "Ohne Feedback", "correct": false, "because": "Verpasst Optimierung"}]');
